import { CannotCreatingAddress, CannotUpdatingAddress, notFoundError } from "../errors";
import addressRepository from "../repositories/addressRepository";
import { AddressType } from "../utils/protocols";
import peopleService from "./peopleService";

async function createAddress(street: string, number: string, neighborhood: string, cep: string, city: string, state: string, addressDetail: string, peopleId: number): Promise<AddressType> {
	await peopleService.getPeopleById(peopleId);

	const checkAddress = await addressRepository.checkAddressesEquals(street, number, neighborhood, cep, city, state, addressDetail);

	if (checkAddress) {
		throw CannotCreatingAddress();
	}

	const result = await addressRepository.create(street, number, neighborhood, cep, city, state, addressDetail, peopleId);

	return result;
}

async function getAddresses() {
	const result = await addressRepository.listOfAddresses();
	return result;
}

async function getAddressById(addressId: number) {
	const result = await addressRepository.findAddressById(addressId);

	if (!result) {
		throw notFoundError();
	}

	return result;
}

async function updateAddress(addressId: number, street: string, number: string, neighborhood: string, cep: string, city: string, state: string, addressDetail: string, peopleId: number): Promise<AddressType> {
	await getAddressById(addressId);
	await peopleService.getPeopleById(peopleId);
	const checkAddress = await addressRepository.checkAddressesEquals(street, number, neighborhood, cep, city, state, addressDetail);

	if (checkAddress) {
		throw CannotUpdatingAddress();
	}

	const result = await addressRepository.update(addressId, street, number, neighborhood, cep, city, state, addressDetail, peopleId);

	return result;
}

async function deleteAddressById(addressId: number) {
	await getAddressById(addressId);

	const result = await addressRepository.deleteAddressById(addressId);

	return result;
}

export default { createAddress, getAddresses, getAddressById, updateAddress, deleteAddressById };

import { Phone, Address } from "@prisma/client";
import peopleRepository from "../repositories/peopleRepository";
import { PeopleType, WithoutAddressId, WithoutPhoneId } from "../utils/protocols";
import { notFoundError, CannotCreatingPeople, CannotUpdatingPeople, CannotUpdatingWithout } from "../errors";

async function createPeople(name: string, cpfCnpj: string, dtNascimento: string, email: string, pessoaJuridicacode: boolean, phones: Phone[], addresses: Address[]): Promise<PeopleType> {
	const resultOfPeople = await peopleRepository.getPeopleByCpfCnpj(cpfCnpj);
	if (resultOfPeople) {
		throw CannotCreatingPeople();
	}

	const result = await peopleRepository.createPeople(name, cpfCnpj, dtNascimento, email, pessoaJuridicacode, phones, addresses);

	return result;
}

async function getPeoples() {
	const result = await peopleRepository.findPeople();
	return result;
}

async function getPeopleById(peopleId: number) {
	const result = await peopleRepository.findPeopleById(peopleId);

	if (!result) {
		throw notFoundError();
	}
	return result;
}

async function updatePeople(peopleId: number, name: string, cpfCnpj: string, dtNascimento: string, email: string, pessoaJuridicacode: boolean, ativo: boolean, phones: Phone[], addresses: Address[]): Promise<PeopleType> {
	const { cpf_cnpj } = await getPeopleById(peopleId);

	if (cpfCnpj && cpfCnpj !== cpf_cnpj) {
		const resultOfPeople = await peopleRepository.getPeopleByCpfCnpj(cpfCnpj);

		if (resultOfPeople) {
			throw CannotUpdatingPeople();
		}
	}

	if (phones) {
		phones.map(phone => {
			if (phone.id === undefined) throw CannotUpdatingWithout(WithoutPhoneId);
		});
	}

	if (addresses) {
		addresses.map(address => {
			if (address.id === undefined) throw CannotUpdatingWithout(WithoutAddressId);
		});
	}

	const result = await peopleRepository.updatePeople(peopleId, name, cpfCnpj, dtNascimento, email, pessoaJuridicacode, ativo, phones, addresses);

	return result;
}

async function deletePeopleById(peopleId: number) {
	await getPeopleById(peopleId);

	const result = await peopleRepository.deletePeople(peopleId);

	return result;
}

export default { createPeople, getPeoples, getPeopleById, updatePeople, deletePeopleById };

import { notFoundError } from "../errors";
import phoneRepository from "../repositories/phoneRepository";
import { PhoneType } from "../utils/protocols";
import peopleService from "./peopleService";

async function createPhone(numero: string, tipoTelefone: string, peopleId: number): Promise<PhoneType> {
	await peopleService.getPeopleById(peopleId);

	const result = await phoneRepository.create(numero, tipoTelefone, peopleId);

	return result;
}

async function getPhones() {
	const result = await phoneRepository.listOfPhones();
	return result;
}

async function getPhoneById(phoneId: number) {
	const result = await phoneRepository.findPhoneById(phoneId);

	if (!result) {
		throw notFoundError();
	}

	return result;
}

async function updatePhone(phoneId: number, numero: string, tipoTelefone: string, peopleId: number): Promise<PhoneType> {
	await getPhoneById(phoneId);
	await peopleService.getPeopleById(peopleId);

	const result = await phoneRepository.update(phoneId, numero, tipoTelefone, peopleId);

	return result;
}

async function deletePhoneById(phoneId: number) {
	await getPhoneById(phoneId);

	const result = await phoneRepository.deletePhoneById(phoneId);

	return result;
}

export default { createPhone, getPhones, getPhoneById, updatePhone, deletePhoneById };

